class Solution {
  private static final long MOD = 1_000_000_007L;

  private static long[][] mul(long[][] a, long[][] b, int K) {
    long[][] c = new long[K][K];
    for (int i = 0; i < K; i++) {
      for (int k = 0; k < K; k++) {
        long x = a[i][k];
        if (x == 0) continue;
        for (int j = 0; j < K; j++) c[i][j] = (c[i][j] + x * b[k][j]) % MOD;
      }
    }
    return c;
  }

  public int zigZagArrays(int n, int l, int r) {
    int K = r - l + 1;
    long[][] m = new long[K][K];
    // newUp[v] = sum of up[w] for w > K - 1 - v
    for (int v = 0; v < K; v++) for (int w = K - v; w < K; w++) m[v][w] = 1;
    long[][] res = new long[K][K];
    for (int i = 0; i < K; i++) res[i][i] = 1;
    for (long e = n - 2; e > 0; e >>= 1) {
      if ((e & 1) == 1) res = mul(res, m, K);
      m = mul(m, m, K);
    }
    long sum = 0;
    for (int v = 0; v < K; v++) {
      for (int w = 0; w < K; w++) sum = (sum + res[v][w] * w) % MOD;
    }
    return (int) (sum * 2 % MOD);
  }
}
